mod lexer;
use lexer::Lexer;
use std::env;
use std::fs;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("usage: mycc <file>");
        return;
    }
    let source = fs::read_to_string(&args[1]).expect("Failed to read file");
    let mut lexer = Lexer::new(&source);
    let tokens = lexer.tokenize();
    for token in &tokens {
        println!("{:?}", token);
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    // TODO: define token variants
    // e.g., Integer(i64), Float(f64), String(String),
    // Identifier(String), Plus, Minus, Star, Slash,
    // LeftParen, RightParen, LeftBrace, RightBrace,
    // Semicolon, Equals, If, Else, While, Return, Func, Let, Int, Float, Bool, Print,
    EOF,
}

pub struct Lexer {
    input: Vec<char>,
    pos: usize,
}

impl Lexer {
    pub fn new(input: &str) -> Self {
        Lexer {
            input: input.chars().collect(),
            pos: 0,
        }
    }

    pub fn tokenize(&mut self) -> Vec<Token> {
        let mut tokens = Vec::new();
        // TODO: scan characters and produce tokens
        tokens.push(Token::EOF);
        tokens
    }
}

